@app.get("/docs/<name>")
def docs(name):
    allowed = {"intro.txt", "help.txt", "faq.txt"}
    chosen = (name or "").strip()
    if chosen not in allowed:
        return "missing", 404
    full = os.path.normpath(os.path.join(DOC_ROOT, chosen))
    if not full.startswith(os.path.abspath(DOC_ROOT) + os.sep):
        return "forbidden", 403
    with open(full, "r", encoding="utf-8") as fh:
        body = fh.read()
    return Response(body, mimetype="text/plain")

